async function installStudioSkill({
  skillId,
  dataRoot,
  hostSkillsDir = HOST_SKILL_DIR,
  catalog = [],
  pluginRoot: pluginRoot2,
  overwrite = false
} = {}) {
  if (!SKILL_NAME_PATTERN.test(skillId || "") || isReservedId(skillId)) {
    return fail(`\u4E0D\u80FD\u5B89\u88C5\u8FD9\u4E2A Skill\uFF1A${skillId || "\u672A\u77E5"}\u3002`);
  }
  const hostRoot = path4.resolve(hostSkillsDir);
  if (path4.basename(hostRoot) === ".system" || hostRoot.includes(`${path4.sep}.system${path4.sep}`)) {
    return fail("\u4E0D\u80FD\u5B89\u88C5\u5230 Codex \u7684 .system Skill \u76EE\u5F55\u3002");
  }
  const catalogEntry = catalog.find((entry) => entry.id === skillId);
  if (catalogEntry?.origin === "host") {
    return fail("\u5BBF\u4E3B\u81EA\u5E26\u7684 Skill \u4E0D\u80FD\u518D\u5B89\u88C5\u5230\u5185\u7F6E\u76EE\u5F55\u3002");
  }
  const candidates = [
    registeredSkillDir(dataRoot, skillId),
    catalogSkillDirectory(catalogEntry),
    pluginRoot2 ? path4.join(pluginRoot2, "skills", skillId) : null
  ].filter(Boolean);
  let sourceDir = null;
  for (const candidate of candidates) {
    const skillInfo = await pathInfo(path4.join(candidate, "SKILL.md"));
    if (skillInfo?.isFile()) {
      sourceDir = candidate;
      break;
    }
  }
  if (!sourceDir) return fail(`Studio \u91CC\u627E\u4E0D\u5230 Skill ${skillId}\u3002`);
  const destination = path4.join(hostRoot, skillId);
  if (isInside(destination, path4.join(hostRoot, ".system"))) {
    return fail("\u4E0D\u80FD\u5B89\u88C5\u5230 Codex \u7684 .system Skill \u76EE\u5F55\u3002");
  }
  const existing = await pathInfo(destination);
  if (existing && !overwrite) {
    return fail(`~/.codex/skills/${skillId} \u5DF2\u7ECF\u5B58\u5728\u3002\u5982\u9700\u66F4\u65B0\uFF0C\u8BF7\u6253\u5F00\u8986\u76D6\u3002`);
  }
  try {
    await copySkillDirectory(sourceDir, destination);
  } catch (error51) {
    return fail(error51 instanceof Error ? error51.message : String(error51));
  }
  return { ok: true, destination, skillId };
}

